using Alpinarc.Api.Stages;

namespace Alpinarc.Api.Tours;

/// <summary>An ordered list of stages. The stages don't have to connect.</summary>
public sealed class Tour
{
    /// <summary>Generated by Postgres on insert.</summary>
    public Guid Id { get; init; }

    public required string Name { get; set; }

    public string? Description { get; set; }

    /// <summary>Generated by Postgres on insert.</summary>
    public DateTimeOffset CreatedAt { get; init; }

    /// <summary>In no particular order when loaded: sort by <see cref="TourStage.Position"/>.</summary>
    public List<TourStage> Stages { get; init; } = [];
}

/// <summary>A stage's place in a tour. A tour may use the same stage more than once.</summary>
public sealed class TourStage
{
    public Guid TourId { get; set; }

    public Tour Tour { get; set; } = null!;

    /// <summary>1-based. Only the order of the stages: tours don't model days.</summary>
    public int Position { get; set; }

    public Guid StageId { get; set; }

    public Stage Stage { get; set; } = null!;
}
